#include <algorithm>
#include <chrono>
#include <cstdint>
#include <iostream>
#include <numeric>
#include <random>
#include <string>
#include <vector>
using Clock=std::chrono::steady_clock; static constexpr uint64_t SEED=0xB0D2A018ULL;
static inline uint64_t mix64(uint64_t x){x+=0x9e3779b97f4a7c15ULL;x=(x^(x>>30))*0xbf58476d1ce4e5b9ULL;x=(x^(x>>27))*0x94d049bb133111ebULL;return x^(x>>31);} static inline uint64_t fnv1a(const std::string&s,uint64_t h=1469598103934665603ULL){for(unsigned char c:s){h^=c;h*=1099511628211ULL;}return h;}
struct A{uint32_t rho;uint64_t fp;};static inline A enc(const std::string&k,uint32_t M){uint64_t h0=mix64(fnv1a(k)),h1=mix64(h0^0xD6E8FEB86659FD93ULL),h2=mix64(h1^0xA5A35625D3E7E5B9ULL),h3=mix64(h2^0x9E3779B97F4A7C15ULL);return{uint32_t(h0%M),mix64(h0^(h1<<1)^(h2>>1)^h3)};}
struct Slot{uint64_t key=0,val=0;uint32_t dist=0;bool used=false;};
class RH{std::vector<Slot>s;size_t mask;public:explicit RH(size_t n=1){size_t c=8;while(c<n*2)c<<=1;s.resize(c);mask=c-1;}void put(uint64_t k,uint64_t v){size_t i=mix64(k)&mask;Slot cur{k,v,0,true};for(;;){auto&x=s[i];if(!x.used){x=cur;return;}if(x.key==cur.key){x.val=v;return;}if(x.dist<cur.dist)std::swap(x,cur);i=(i+1)&mask;++cur.dist;}}bool get(uint64_t k,uint64_t&v)const{size_t i=mix64(k)&mask;uint32_t d=0;for(;;){auto&x=s[i];if(!x.used||x.dist<d)return false;if(x.key==k){v=x.val;return true;}i=(i+1)&mask;++d;}}size_t bytes()const{return s.capacity()*sizeof(Slot);}};
class PartitionedRH{uint32_t M;std::vector<RH*>tabs;public:PartitionedRH(uint32_t m,const std::vector<A>&as):M(m),tabs(m,nullptr){std::vector<size_t>c(M);for(auto&a:as)c[a.rho]++;for(uint32_t i=0;i<M;++i)if(c[i])tabs[i]=new RH(c[i]);}~PartitionedRH(){for(auto*p:tabs)delete p;}void put(const A&a,uint64_t v){tabs[a.rho]->put(a.fp,v);}bool get(const std::string&k,uint64_t&v)const{auto a=enc(k,M);auto*t=tabs[a.rho];return t&&t->get(a.fp,v);}size_t bytes()const{size_t b=tabs.capacity()*sizeof(void*);for(auto*p:tabs)if(p)b+=p->bytes();return b;}};
struct Stat{double mean,p99,tput;};template<class F>Stat bench(F&&f,const std::vector<std::string>&ks,const std::vector<size_t>&q){std::vector<double>l;l.reserve(q.size());volatile uint64_t sink=0;auto A0=Clock::now();for(auto i:q){auto a=Clock::now();uint64_t v=0;f(ks[i],v);auto b=Clock::now();sink^=v;l.push_back(std::chrono::duration<double,std::micro>(b-a).count());}auto B=Clock::now();std::sort(l.begin(),l.end());return{std::accumulate(l.begin(),l.end(),0.0)/l.size(),l[size_t(.99*(l.size()-1))],q.size()/std::chrono::duration<double>(B-A0).count()};}
static std::vector<std::string> keys(const std::string&w,size_t N,uint32_t M){std::vector<std::string>o;o.reserve(N);if(w=="hotrho"){uint32_t hot=std::max(1u,M/32);uint64_t c=0;while(o.size()<N){auto k="H"+std::to_string(c++);if(enc(k,M).rho<hot)o.push_back(k);}}else for(size_t i=0;i<N;++i)o.push_back("K_"+std::to_string(i));return o;}
int main(int argc,char**argv){size_t N=argc>1?std::stoull(argv[1]):100000,Q=50000;uint32_t M=2048;std::cout<<"workload,engine,mean_us,p99_us,throughput_ops_s,approx_bytes_per_record\n";for(std::string w:{"sequential","hotrho"}){auto ks=keys(w,N,M);std::vector<A>as;as.reserve(N);for(auto&k:ks)as.push_back(enc(k,M));std::mt19937_64 r(SEED);std::uniform_int_distribution<size_t>d(0,N-1);std::vector<size_t>q(Q);for(auto&x:q)x=d(r);RH global(N);for(size_t i=0;i<N;++i)global.put(as[i].fp,i);auto sg=bench([&](auto&k,uint64_t&v){return global.get(enc(k,M).fp,v);},ks,q);std::cout<<w<<",global_robin_hood,"<<sg.mean<<','<<sg.p99<<','<<sg.tput<<','<<double(global.bytes())/N<<'\n';PartitionedRH local(M,as);for(size_t i=0;i<N;++i)local.put(as[i],i);auto sl=bench([&](auto&k,uint64_t&v){return local.get(k,v);},ks,q);std::cout<<w<<",rho_partitioned_robin_hood,"<<sl.mean<<','<<sl.p99<<','<<sl.tput<<','<<double(local.bytes())/N<<'\n';}}
